import { IBaseArticle } from '@apps/Articles/@types/articles.types';
import PohInput, { IPohInputProps } from '@ui-kit/Input';

import { selectArticleAsync } from '../ArticleSelectModal';

interface IArticleSelectProps extends Omit<IPohInputProps, 'value' | 'onChange'> {
  value: Pick<IBaseArticle, 'id' | 'name'> | null;
  onChange?: (v: IBaseArticle) => void;
}

const ArticleSelectInput = ({ value, onChange, ...props }: IArticleSelectProps) => {
  return (
    <PohInput
      readOnly
      placeholder="Выберите статью"
      name="id_article"
      className="w-100 flex-grow-1"
      {...props}
      value={value?.name || ''}
      onClick={() => {
        selectArticleAsync({ filter: {} }).then((article) => {
          onChange?.(article);
        });
      }}
    />
  );
};

export default ArticleSelectInput;
