import { IGetArticlesCriteria } from '@apps/Articles/@types/articles.dto.types';
import { IArticle } from '@apps/Articles/@types/articles.types';
import { showModal } from '@ui-kit/Modal';

import ArticlesList from '../ArticlesList';

interface IArticleSelectModalProps {
  filter: IGetArticlesCriteria;
  onSelect: (ro: IArticle) => void;
}

const ArticleSelectModal = ({ filter, onSelect }: IArticleSelectModalProps) => {
  return (
    <div style={{ overflowY: 'auto', minWidth: 400, maxHeight: 300 }}>
      <ArticlesList
        {...filter}
        withSearch
        listItemPatcher={(x) => ({
          onClick: (e) => {
            e.preventDefault();
            onSelect(x);
          },
        })}
      />
    </div>
  );
};

export function selectArticleAsync({
  filter,
  title = 'Выбор статьи',
}: {
  filter: IGetArticlesCriteria;
  title?: string;
}): Promise<IArticle> {
  return new Promise((resolve) => {
    showModal({
      size: 'sm',
      title: title,
      children: (closeHandler: () => void) => (
        <ArticleSelectModal
          filter={filter}
          onSelect={(s) => {
            resolve(s);
            closeHandler();
          }}
        />
      ),
    });
  });
}
